body.onloadscript:

layoutBtnObj.btn('add').setHide();
layoutBtnObj.btn('save').setShow();
layoutBtnObj.btn('delete').setHide();
layoutBtnObj.btn('confirm').setHide();
layoutBtnObj.btn('copy').setHide();
layoutBtnObj.btn('update').setHide();
layoutBtnObj.btn('cancel').setHide();
formObj.hideItem("SELLER_CODE");
//layoutBtnObj.btn('FORCE_LOGON').setHide();
if (Sepoa.info.USER_TYPE == 'S') {

    formObj.hideItem("COMPANY_CODE");
    formObj.hideItem("PLANT_CODE");
    formObj.hideItem("DEPT");
    formObj.hideItem("USER_TYPE");
    formObj.hideItem("WORK_TYPE");
    formObj.hideItem("VENDOR_SEARCH");
    formObj.hideItem("MENU_PROFILE_CODE");

}
formObj.setReadOnly("DEPT", true);
formObj.setReadOnly("DEPT_NAME", true);

window.jusoCallBack = jusoCallBack;




    if (id == 'CHECK_ID') {
        var user_id = formObj.getValue("USER_ID");
        if (user_id == '') {
            Alert(Sepoa.cache.text.get('MESSAGE.5405')); // 아이디를 입력하세요.
        } else {
            checkID(id);
        }
    } else if (id == 'VENDOR_SEARCH') {
        if (formObj.getValue("USER_TYPE") != "S") {
            Message(Sepoa.cache.text.get("MESSAGE.USER_TYPE_CHECK"));
        } else {
            PopupCommonPost('SP0018', setSeller, [Sepoa.info.HOUSE_CODE, Sepoa.info.COMPANY_CODE]);
        }
    } else if (id == 'COST_IMG') {
        PopupCommonPost('SP0001', setCostCenter, [Sepoa.info.HOUSE_CODE, Sepoa.info.LANGUAGE, 'UX038']);
    } else if (id == 'DEPT_IMG') {
        var companyCode = formObj.getValue("COMPANY_CODE");
        if (companyCode == '') {
            Alert(Sepoa.cache.text.get("AD_102_T.MESSAGE_0001"));
            return;
        }
        //PopupOpenPost('/Admin/OrganizationManagement/AdminOrganizationManagementDepartmentTree.sux', {
        //COMPANY_CODE: companyCode
        //}, setDept, 600, '', '부서목록');
        PopupCommonPost('SP0015', setDept, [Sepoa.info.HOUSE_CODE, companyCode]);
    } else if (id == "ADDR_SEARCH") {
        var pop = window.open(window.CONTEXT_NAME+"/resource/plugin/jusoPopup/jusoPopup.jsp", "jusoCallBack", "width=570,height=420, scrollbars=yes, resizable=yes");
    }

userscript.function:

		let result_flag;

		doServiceAjax('sepoa.svc.admin.AD_019_2', 'CONNECTION', 'doCheckId', {
            USER_ID: formObj.getValue("USER_ID"),
            HOUSE_CODE : Sepoa.info.HOUSE_CODE, 
            COMPANY_CODE : Sepoa.info.COMPANY_CODE
        }, function(so) {
        	if (so.status == 1) {
        		var result = new SepoaFormater(so.result[0]).getArrayMap()[0];
        		if(result.CNT > 0){
              		dataOutput.setValue('CHECK_ID', 'N'); //안됨
              		result_flag = false; 
             	}else{
             		dataOutput.setValue('CHECK_ID', 'Y'); //됨
             		result_flag = true;
             	}
            return;
         	}
        },false);

        if(id=='CHECK_ID'){
        	if(dataOutput.getValue('CHECK_ID') == 'N'){
        		Alert( "해당 ["+formObj.getValue("USER_ID")+"] 는 사용할수 없는 ID 입니다.");
        	}else{
        		Alert("해당 ["+formObj.getValue("USER_ID")+"] 는 사용하실 수 있는 ID 입니다.");
        	}
        }

        return result_flag;


if (id == 'save') {
    doFormSave();
} else if (id == 'FORCE_LOGON') {
    changeUserLogon();
} else if (id == 'add') {
    doAdd();
} else if (id == 'VENDOR_SEARCH') {
    if (formObj.getValue("USER_TYPE") == "S") {
        Alert(Sepoa.cache.text.get("MESSAGE.USER_TYPE_CHECK"));
    } else {
        PopupCommonPost('SP0018', setSeller, [Sepoa.info.HOUSE_CODE, Sepoa.info.COMPANY_CODE]);
    }

} else if (id == 'delete') {
    doDelete();
} else if(id == 'RESET_PW') {
    doResetPassword();
}


	var userId = formObj.getValue("USER_ID");
	var userName= formObj.getValue("USER_NAME_LOC");
	if (!userId) {
		Alert(Sepoa.cache.text.get('AD_019_2.SELECT_USER'));
        return;
    }
    PopupOpenPost('/UxDefault/Common/PasswordReset.sux', {
    	USER_ID: userId, USER_NAME : userName
    }, null, 400, 400, Sepoa.cache.text.get('AD_019_2.RESET_PASSWORD'));


if (name == 'COMPANY_CODE') {
    if (formObj.getValue('COMPANY_CODE') != "") {
        //formObj.reloadComboBox('PLANT_CODE', ['SL0014', Sepoa.info.HOUSE_CODE + "#" + formObj.getValue('COMPANY_CODE')]);
        formObj.reloadComboBox('DEPT', ['SL0015', Sepoa.info.HOUSE_CODE + "#" + formObj.getValue('COMPANY_CODE')]);
    }
}
if (name == 'USER_TYPE') {
    if(value != ''){
        if (value == "S") {
            formObj.hideItem("COMPANY_CODE");
            //formObj.hideItem("PLANT_CODE");
            formObj.hideItem("DEPT");
        } else {
            formObj.showItem("COMPANY_CODE");
            //formObj.showItem("PLANT_CODE");
            formObj.showItem("DEPT");
        }
    }
}


var user_id = formObj.getValue("USER_ID");
if (!user_id) {
    return;
}
var params = {
    ID: user_id,
}
doServiceAjax('sepoa.svc.admin.AD_019_2', 'CONNECTION', 'changeUserLogon', params, function(so) {
    if (so.status == 0) {
        Alert(so.message);
    } else if (so.status == 1) {
        SUX.root.location.href = window.CONTEXT_NAME + "/Main.sux";
    }
});


var data = [];
data.push(formObj.getValue('COMPANY_CODE'));
data.push(formObj.getSelectedOption('COMPANY_CODE'));
data.push('ctrl');
data.join(',');
return data;


formObj.clear(true);
formObj.setReadOnly("USER_ID", false);
formObj.setReadOnly("CHECK_ID", false);
dataOutput.setValue('load_Id', "false");
if (Sepoa.info.USER_TYPE == 'S') {
    formObj.setValue("USER_TYPE", "S");
    formObj.setValue("WORK_TYPE", "G");
    formObj.setValue("SELLER_CODE", Sepoa.info.COMPANY_CODE);
    //formObj.setValue("SELLER_NAME_LOC", Sepoa.info.NAME_LOC);
    formObj.setValue("MENU_PROFILE_CODE", Sepoa.config.get("sepoa.supplier.default.profile_code"));
}
//formObj.setValue("TIME_ZONE", "GMT9");
//formObj.setValue("DATE_FORMAT", "%Y/%m/%d");
formObj.setValue("COUNTRY", "KR");
formObj.setValue("LANGUAGE", "KO");


layoutBtnObj.btn('save').setShow();
layoutBtnObj.btn('delete').setHide();


Confirm(Sepoa.cache.text.get('MESSAGE.1015'), function(result) { // 삭제 하시겠습니까?
    if (result) {
        var formResult = doServiceAjax('sepoa.svc.admin.AD_019_2', 'TRANSACTION', 'doDelete', null, function(formResult) {
            if (formResult.status == 1) {
                Alert(Sepoa.cache.text.get('MESSAGE.5107'));
                callFunction(['AD_019_A'], 'doQuery_UserList', ['']);
                callFunction(['AD_019_B'], 'doQuery_standbyUserList', ['']);
                doAdd();
                return;
            } else if (formResult.status == 2){
            	Alert('시스템 관리자는 삭제할 수 없습니다.');
            } else {
                Alert(formResult.message);
            }
        });
    }
});


	dataOutput.setValue('CHECK_ID', 'Y');
	dataOutput.setValue('load_Id', "true");
    var formResult = doServiceAjax('sepoa.svc.admin.AD_019_2', 'CONNECTION', 'doFormLoad', {
        USER_ID: user_id
    }, function(formResult) {
        if (formResult.status != 1) {
            Alert(formResult.message);
            return;
        }

        var sf = new SepoaFormater(formResult.result[0]);
        if (sf.getRowCount() > 0) {
            formObj.dataMapper(sf);
        }
        layoutBtnObj.btn('save').setShow();
        layoutBtnObj.btn('delete').setShow();
        formObj.setReadOnly("USER_ID", true);
        formObj.setReadOnly("CHECK_ID", true);
        formObj.setReadOnly("SELLER_CODE", true);
        formObj.setReadOnly("SELLER_NAME_LOC", true);
    });


        	if (!formObj.validate()) {
                Alert(Sepoa.cache.text.get('MESSAGE.0002'));
                return;
        	}

        	let loadData = dataOutput.getValue('load_Id'); //true 기존데이터 

        	if(loadData == "false"){
	        	if(!checkID()){
	        		Alert("아이디 변경 후 ID중복체크 해주시기 바랍니다.");
	        		return;
	        	}
        	}

            if (formObj.getValue('PASSWORD_1').length > 0) {
                if (LRTrim(formObj.getValue('PASSWORD_1')) != LRTrim(formObj.getValue('PASSWORD_2'))) {
                    Alert(Sepoa.cache.text.get('MESSAGE.1039')); //비밀번호가 일치하지 않습니다.
                    return;
                } else if (checkPass(formObj.getValue('PASSWORD_1')) == false) {
                    Alert(Sepoa.cache.text.get('AD_051.MESSAGE_0002')); // 비밀번호는 영문+숫자로 8자 이상 20자 이하로 조합 해주세요
                    return;
                }
            }
            if(formObj.getValue('MENU_PROFILE_CODE') == Sepoa.config.get('sepoa.seal.manager.porfile.code').toUpperCase() || 
            	formObj.getValue('MENU_PROFILE_CODE') == Sepoa.config.get('sepoa.legal.porfile.code').toUpperCase()){
            	if(formObj.getValue('USER_TYPE') == ''){
            		Alert("공지 대상을 지정해주세요."); 
                    return;
            	}
            }

            Confirm(Sepoa.cache.text.get('MESSAGE.1018'), function(result) {
                if (result) {
                    var formResult = doServiceAjax('sepoa.svc.admin.AD_019_2', 'TRANSACTION', 'doFormSave', null, function(formResult) {
                        if (formResult.status == 1) {
                            Alert(Sepoa.cache.text.get('MESSAGE.1022'));
                            doFormLoad(formObj.getValue('USER_ID'));
                            callFunction(['AD_019_A'], 'doQuery_UserList', ['']);
                            callFunction(['AD_019_B'], 'doQuery_standbyUserList', ['']);
                            return;
                        } else {
                            Alert(formResult.message);
                        }
                    });
                }
            });


if (formObj.getValue('COMPANY_CODE') != "") {
    formObj.reloadComboBox('PLANT_CODE', ['SL0014', Sepoa.info.HOUSE_CODE + "#" + formObj.getValue('COMPANY_CODE')]);
    formObj.reloadComboBox('DEPT', ['SL0015', '{HOUSE_CODE}#' + formObj.getValue('COMPANY_CODE')]);
}

if (formObj.getValue('USER_TYPE') == "S") {
    formObj.hideItem("COMPANY_CODE");
    formObj.hideItem("PLANT_CODE");
    formObj.hideItem("DEPT");
    formObj.hideItem("DEPT_IMG");
    formObj.hideItem("EMPLOYEE_NO");
    formObj.hideItem("COSTCENTER_CODE");
} else {
    formObj.showItem("COMPANY_CODE");
    formObj.showItem("PLANT_CODE");
    formObj.showItem("DEPT");
    formObj.showItem("DEPT_IMG");
    formObj.showItem("EMPLOYEE_NO");
    formObj.showItem("COSTCENTER_CODE");
}


if (name == 'USER_TYPE' && value == 'B') {
    formObj.hideItem("SELLER_NAME_LOC");
    formObj.hideItem("VENDOR_SEARCH");
    formObj.hideItem("SELLER_CODE");
} else {
    formObj.showItem("SELLER_NAME_LOC");
    formObj.showItem("VENDOR_SEARCH");
    formObj.showItem("SELLER_CODE");
}


doServiceAjax('sepoa.svc.admin.AD_019_2', 'TRANSACTION', 'tempPWreset', null, function(so) {
    if (so.status == 1) {
        Alert(Sepoa.cache.text.get('MESSAGE.1022'));
    } else {
        Alert(so.message);
    }
});
